INSERT INTO `guided_steps` (`lesson_id`, `step_order`, `prompt`, `correct_snippet`, `distractor_1`, `distractor_2`, `distractor_3`) VALUES
(139, 1, 'Which Java statement declares an int named lives and initializes it to 3?', 'int lives = 3;', 'int lives = "3";', 'int lives = 3', 'lives int = 3;'),
(140, 1, 'Which code declares a char named option and then assigns \'C\' to it?', 'char option; option = \'C\';', 'char option; option = "C";', 'char option; option == \'C\';', 'char option; option = \'C\''),
(141, 1, 'Which statement declares a double named grade and initializes it to 0.0?', 'double grade = 0.0;', 'double grade = "0.0";', 'double grade == 0.0;', 'double grade = 0.0'),
(142, 1, 'Which code follows the guideline of declaring one variable per line?', 'double exam = 0; double quiz = 10; double grade = 0;', 'double exam = 0, quiz = 10, grade = 0;', 'double exam = 0; quiz = 10; grade = 0;', 'double exam = 0; double quiz = 10; double grade = 0'),
(143, 1, 'Which code declares a boolean named result and then assigns true to it?', 'boolean result; result = true;', 'boolean result; result = "true";', 'boolean result; result = True;', 'bool result; result = true;'),
(144, 1, 'Which code prints the value stored in the int variable value?', 'int value = 10; System.out.println(value);', 'int value = 10; System.out.println("value");', 'int value = 10; System.out.println(value)', 'int value = 10; system.out.println(value);'),
(145, 1, 'Which code prints The value of x=A by joining text with a char variable?', 'char x = \'A\'; System.out.println("The value of x=" + x);', 'char x = \'A\'; System.out.println("The value of x=" + "x");', 'char x = \'A\'; System.out.println("The value of x=", x);', 'char x = "A"; System.out.println("The value of x=" + x);'),
(146, 1, 'Which code prints Hello world! on a single line?', 'System.out.print("Hello "); System.out.print("world!");', 'System.out.println("Hello "); System.out.println("world!");', 'System.out.println("Hello "); System.out.print("world!");', 'System.out.print("Hello ") System.out.print("world!");'),
(147, 1, 'Which statement stores the sum of 37 and 42 in an int named sum?', 'int sum = 37 + 42;', 'int sum = 37 - 42;', 'int sum = "37 + 42";', 'int sum = 37 + 42'),
(148, 1, 'Which code stores the remainder of i divided by j?', 'int i = 37; int j = 42; int remainder = i % j;', 'int i = 37; int j = 42; int remainder = i / j;', 'int i = 37; int j = 42; int remainder = i * j;', 'int i = 37; int j = 42; int remainder = i % j'),
(149, 1, 'Which statement stores 42 + 7.22 in a double named total?', 'double total = 42 + 7.22;', 'int total = 42 + 7.22;', 'double total = 42 - 7.22;', 'double total = "42 + 7.22";'),
(150, 1, 'Which code uses pre-increment so that k becomes 14?', 'int i = 10; int j = 3; int k = 0; k = ++j + i;', 'int i = 10; int j = 3; int k = 0; k = j++ + i;', 'int i = 10; int j = 3; int k = 0; k = --j + i;', 'int i = 10; int j = 3; int k = 0; k = ++j - i;'),
(151, 1, 'Which code declares count as 0 and then increases it by 1?', 'int count = 0; count++;', 'int count = 0; count--;', 'int count = 0; count+1;', 'int count = 0; count++'),
(152, 1, 'Which code stores whether j and k are equal in a boolean named same?', 'int j = 42; int k = 42; boolean same = j == k;', 'int j = 42; int k = 42; boolean same = j = k;', 'int j = 42; int k = 42; boolean same = j != k;', 'int j = 42; int k = 42; int same = j == k;'),
(153, 1, 'Which code uses short-circuit AND so that j++ is never evaluated?', 'int i = 0; int j = 10; boolean test = false; test = (i > 10) && (j++ > 9);', 'int i = 0; int j = 10; boolean test = false; test = (i > 10) & (j++ > 9);', 'int i = 0; int j = 10; boolean test = false; test = (i > 10) || (j++ > 9);', 'int i = 0; int j = 10; boolean test = false; test = (i > 10) && (j++ > 9)'),
(154, 1, 'Which code uses short-circuit OR so that j++ is never evaluated?', 'int i = 0; int j = 10; boolean test = false; test = (i < 10) || (j++ > 9);', 'int i = 0; int j = 10; boolean test = false; test = (i < 10) | (j++ > 9);', 'int i = 0; int j = 10; boolean test = false; test = (i < 10) && (j++ > 9);', 'int i = 0; int j = 10; boolean test = false; test = (i > 10) || (j++ > 9);'),
(155, 1, 'Which code stores the exclusive OR of val1 and val2 in a boolean named xor?', 'boolean val1 = true; boolean val2 = false; boolean xor = val1 ^ val2;', 'boolean val1 = true; boolean val2 = false; boolean xor = val1 && val2;', 'boolean val1 = true; boolean val2 = false; boolean xor = val1 || val2;', 'boolean val1 = true; boolean val2 = false; boolean xor = val1 ^^ val2;'),
(156, 1, 'Which code stores the logical NOT of val1 in a boolean named flipped?', 'boolean val1 = true; boolean flipped = !val1;', 'boolean val1 = true; boolean flipped = val1!;', 'boolean val1 = true; boolean flipped = val1;', 'boolean val1 = true; boolean flipped = ~val1;'),
(157, 1, 'Which code uses the conditional operator to store Passed when grade is at least 60?', 'int grade = 80; String status = (grade >= 60) ? "Passed" : "Fail";', 'int grade = 80; String status = (grade >= 60) ? "Fail" : "Passed";', 'int grade = 80; String status = (grade >= 60) ? "Passed" ; "Fail";', 'int grade = 80; String status = (grade >= 60) ? Passed : Fail;'),
(158, 1, 'Which statement adds parentheses to match operator precedence for 6%2*5+4/2+88-10?', 'int result = ((6 % 2) * 5) + (4 / 2) + 88 - 10;', 'int result = (6 % (2 * 5)) + (4 / 2) + 88 - 10;', 'int result = ((6 % 2) * 5) + (4 / 2) + 88 + 10;', 'int result = ((6 % 2) * 5) + (4 / 2) + 88 - 10');

